function prepareConversation(){const c=conversation;audio.stop();c.assisted=false;c.heard=false;c.answer='';c.feedback=null;c.showText=false;c.showMeaning=false;c.revealed=false;renderConversation();}
function sampleReply(t){return t.sample.replace(/Darren/g,state.settings.name).replace(/Edmonton/g,state.settings.home).replace(/Canadá/g,state.settings.country);}
function renderConversation(){
 const c=conversation,t=c.turns[c.index],done=c.feedback?.correct||c.revealed;
 $('#main').innerHTML=`<div class="practice-shell">${practiceTop(c.mission.title,`Turn ${c.index+1} of ${c.turns.length} · ${c.mission.lesson}`,'conversations')}<div class="practice-layout"><section class="task-card"><div class="partner"><div class="partner-icon">${c.mission.taxi?'T':'L'}</div><div><strong>${c.mission.taxi?'Taxi driver':'Lucía'}</strong><small>Take your time. Keep the conversation going.</small></div></div>${audioControls('play-conversation')}${c.showText?`<div class="transcript" lang="es">${esc(t.say)}</div>`:'<button class="text-button" data-action="conversation-text">Show the spoken words</button>'}${c.showMeaning?`<p class="small muted">${esc(t.en)}</p>`:''}<div class="separator"></div><div class="eyebrow">YOUR TURN</div><p>${esc(t.task)}</p><form id="conversation-form" class="response-form"><label for="conversation-answer">${t.audioOnly?'Amount in digits':'Your Spanish response'}</label><div class="response-row"><input id="conversation-answer" autocomplete="off" spellcheck="false" inputmode="${t.audioOnly?'numeric':'text'}" value="${esc(c.answer)}" ${done?'disabled':''}><button type="button" class="mic-button" data-action="mic" data-target="conversation-answer" ${done?'disabled':''}>Say it</button></div>${!done?'<div class="button-row"><button class="button primary" type="submit">Send my response →</button></div>':''}</form>${feedbackHTML(c.feedback)}${done?`<div class="button-row">${button('Hear my response','conversation-my-audio','','secondary')}${button(c.index===c.turns.length-1?'Finish the conversation →':'Continue the conversation →','conversation-next')}</div>`:`<div class="task-help"><button class="text-button" data-action="conversation-hint">A small hint</button><button class="text-button" data-action="conversation-model">Show an example reply</button></div>`}
 <div class="helper-buttons" aria-label="Conversation helpers"><button class="helper-button" data-action="conversation-helper" data-helper="repeat" lang="es">¿Puede repetirlo?</button><button class="helper-button" data-action="conversation-helper" data-helper="slow" lang="es">Más despacio, por favor.</button><button class="helper-button" data-action="conversation-helper" data-helper="meaning" lang="es">No entiendo.</button><button class="helper-button" data-action="conversation-helper" data-helper="write" lang="es">¿Puede escribirlo?</button></div>${note('You can also type or say these requests yourself. A small hint or model marks the turn as supported practice.')}</section><aside class="note help-note taped"><h3>A new connection.</h3><ol class="mission-steps">${c.turns.map((turn,i)=>`<li class="${i===c.index?'current':''}"><span class="step-number">${i<c.index?'✓':i+1}</span><span>${esc(turn.task.split('.')[0])}</span></li>`).join('')}</ol><p class="small">The question stays in Spanish. Reveal its meaning when you need help.</p></aside></div></div>`;
}
function conversationHelper(type,typed=false){
 const c=conversation,t=c.turns[c.index];c.assisted=true;
 const texts={repeat:'¿Puede repetirlo, por favor?',slow:'Más despacio, por favor.',meaning:'No entiendo.',write:'¿Puede escribirlo, por favor?'};const e=findEntry(texts[type]);if(e)record(state,e.id,'use',true,{assisted:!typed});save();
 if(type==='repeat'||type==='slow'){audio.say(t.say,{slow:type==='slow',onEnd:()=>heard(c)});toast(type==='slow'?'Repeating more slowly.':'Repeating the same response.');}
 else{if(type==='write')c.showText=true;else c.showMeaning=true;renderConversation();}
}
function submitConversation(){
 const c=conversation,t=c.turns[c.index];if(c.feedback?.correct||c.revealed)return;const input=$('#conversation-answer').value.trim();if(!input){toast('Try a response first.');return;}c.answer=input;const n=normalize(input);
 if(/repetir|repita|otra vez/.test(n)){conversationHelper('repeat',true);return;}
 if(/despacio|lentamente/.test(n)){conversationHelper('slow',true);return;}
 if(/no entiendo|que significa/.test(n)){conversationHelper('meaning',true);return;}
 if(/escribir|escriba/.test(n)){conversationHelper('write',true);return;}
 if(t.audioOnly&&!c.heard&&!c.showText){toast('Listen to the fare first. You can ask for a repeat or slower speech.');return;}
 const correct=t.accept(n);
 if(correct){
  if(t.audioOnly)record(state,numberId(t.number),c.heard?'listen':'recognize',true,{assisted:c.assisted});
  if(!t.audioOnly)creditUse(input,{assisted:c.assisted});save();c.feedback={correct:true,title:c.assisted?'You kept it going.':'Message received.',message:c.assisted?'You used support this time. Try the turn again in a later conversation.':'Your response fits this exchange.',model:input};c.log.push({question:t.say,answer:input,supported:c.assisted});if(c.assisted)c.supported++;
 }else{c.assisted=true;c.feedback={correct:false,title:'Try a small adjustment.',message:esc(t.hint)};}
 renderConversation();if(!correct)$('#conversation-answer').focus();
}
function conversationModel(){const c=conversation,t=c.turns[c.index];c.assisted=true;c.revealed=true;c.answer=sampleReply(t);c.feedback={correct:false,title:'One way to answer.',message:'Say it aloud. You can also change the details. This is saved as supported practice.',model:c.answer};const e=findEntry(c.answer);if(e)record(state,e.id,t.audioOnly?'listen':'use',false,{assisted:true});save();c.log.push({question:t.say,answer:c.answer,supported:true});c.supported++;renderConversation();}
function nextConversation(){const c=conversation;if(c.index+1<c.turns.length){c.index++;prepareConversation();return;}const old=state.missions[c.mission.id]||{count:0};state.missions[c.mission.id]={count:old.count+1,last:Date.now(),supported:c.supported};save();renderFinish(daily?'Your daily practice, in the journal.':'A conversation to build on.',`You completed “${esc(c.mission.title)}”. ${c.turns.length-c.supported} turns used no hints or model; ${c.supported} used support. Try a later conversation to check what stays with you.`,daily?'Back to my journal':'Meet someone else →',daily?'home':'conversations');daily=false;}
